CREATE POLICY "Users upload own voice notes" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'community-voice-notes' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Authenticated read voice notes" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'community-voice-notes');
CREATE POLICY "Users upload own community photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'community-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Authenticated read community photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'community-photos');